import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { Interactive, Sequence, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// The line draws on from its start, its wiggle calms and swims while it
// settles, it holds, then erases from the start. Frames on the 30 fps scene
// timeline, after `delay` and `speed`. The ids are public: a saved `timing`
// prop refers to them.

type SquiggleElementId = "draw" | "settle" | "erase";

interface SquiggleTimingProps {
  hold?: number;
  erase?: boolean;
}

const DRAW = 24;
const SETTLE = 36;
const ERASE = 18;
const HOLD = 12;

/** The hold, as the scene reads it: a finite count of frames, at least 0. */
const holdOf = (value: number | undefined) =>
  Math.max(
    0,
    typeof value === "number" && Number.isFinite(value) ? value : HOLD,
  );

// The draw and the settle both start on frame 0; the erase follows the
// settle after `hold` frames. Without `erase` the line stays drawn.
const squiggleTimeline = defineTimeline<
  SquiggleElementId,
  SquiggleTimingProps
>((props) => {
  const elements: TimelineElement<SquiggleElementId>[] = [
    { id: "draw", lane: "Line", label: "draw", start: 0, length: DRAW },
    { id: "settle", lane: "Motion", label: "settle", start: 0, length: SETTLE },
  ];
  if (props.erase !== false) {
    elements.push({
      id: "erase",
      lane: "Line",
      label: "erase",
      start: SETTLE + holdOf(props.hold),
      length: ERASE,
      follows: "settle",
    });
  }
  return elements;
});

type SquiggleShape = "wave" | "zigzag" | "loops" | "coil";
type SquiggleJoin = "miter" | "round";

interface SquiggleProps {
  shape?: SquiggleShape;
  x?: number;
  y?: number;
  length?: number;
  angle?: number;
  amplitude?: number;
  wavelength?: number;
  weight?: number;
  color?: string;
  settle?: number;
  hold?: number;
  erase?: boolean;
  delay?: number;
  speed?: number;
  className?: string;
  /**
   * Moves, trims or stretches the draw, the settle and the erase, by the ids
   * in `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<SquiggleElementId>;
}

type Paint = "color" | "className";

interface SquiggleOptions extends Omit<SquiggleProps, Paint> {
  width?: number;
  height?: number;
  fps?: number;
}

interface SquigglePoint {
  x: number;
  y: number;
}

interface SquiggleCurveInput {
  shape: SquiggleShape;
  length: number;
  wavelength: number;
  amplitude: number;
  phase: number;
  unit?: number;
}

const squiggleDefaults: Required<
  Omit<SquiggleProps, "className" | "timing">
> = {
  shape: "wave",
  x: 0.375,
  y: 0.5,
  length: 320,
  angle: 0,
  amplitude: 14,
  wavelength: 48,
  weight: 3,
  color: "#ffffff",
  settle: 0.5,
  hold: HOLD,
  erase: true,
  delay: 0,
  speed: 1,
};

type SmoothShape = Exclude<SquiggleShape, "zigzag">;

const SWIM = 1.5;
const EXIT_SWIM = 0.5;
const TAIL = 14;
const REST = 24;
const MIN_WAVELENGTH = 8;
const LOOP_FLOOR = 3;
const MIN_POINTS = 24;
const MAX_POINTS = 4000;
const EPSILON = 0.01;
const SAMPLES: Record<SmoothShape, number> = { wave: 32, loops: 64, coil: 80 };
const REACH: Record<SmoothShape, number> = { wave: 0, loops: 2.4, coil: 4.2 };

const finite = (value: number | undefined, fallback: number) =>
  typeof value === "number" && Number.isFinite(value) ? value : fallback;
const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));
const round = (value: number) => Math.round(value * 100) / 100;
const rateOf = (speed: number | undefined) =>
  Math.max(0, finite(speed, squiggleDefaults.speed));
const shapeOf = (value: string | undefined): SquiggleShape =>
  value === "zigzag" || value === "loops" || value === "coil" ? value : "wave";
const joinOf = (shape: SquiggleShape): SquiggleJoin =>
  shape === "zigzag" ? "miter" : "round";
const easeOutQuart = (t: number) => 1 - (1 - t) ** 4;
const easeOutCubic = (t: number) => 1 - (1 - t) ** 3;
const easeInOutCubic = (t: number) =>
  t < 0.5 ? 4 * t ** 3 : 1 - (-2 * t + 2) ** 3 / 2;
const easeInOutSine = (t: number) => (1 - Math.cos(Math.PI * t)) / 2;

function smoothstep(value: number) {
  const t = clamp(value, 0, 1);
  return t * t * (3 - 2 * t);
}

/** The schedule without `timing`; it does not read the scene length. */
const scheduleOf = (options: Pick<SquiggleOptions, "hold" | "erase">) =>
  resolve(squiggleTimeline(options, { length: 0 }));

/**
 * The draw, settle and erase spans the helpers below read. `tl` is the
 * resolved schedule; without it the one `options` give, with no `timing`.
 */
function getSquiggleTimeline(
  options: Pick<SquiggleOptions, "hold" | "erase"> = {},
  tl: ResolvedTimeline<SquiggleElementId> = scheduleOf(options),
) {
  const hold = holdOf(options.hold);
  const erase = options.erase !== false;
  const draw = tl.get("draw");
  const settle = tl.get("settle");
  const wipe = erase ? tl.get("erase") : undefined;
  const eraseStart = wipe ? wipe.start : SETTLE + hold;
  const eraseLength = wipe ? wipe.length : ERASE;
  const eraseEnd = eraseStart + eraseLength;
  const end = erase ? eraseEnd : settle.end;
  return {
    draw: draw.length,
    drawAt: draw.start,
    settle: settle.length,
    settleAt: settle.start,
    hold,
    erase,
    eraseStart,
    eraseLength,
    eraseEnd,
    end,
    duration: end + (erase ? TAIL : REST),
  };
}

type SquiggleTimeline = ReturnType<typeof getSquiggleTimeline>;

const squiggleLength = getSquiggleTimeline().end;

function getSquiggleDuration(
  options: Pick<SquiggleOptions, "hold" | "erase" | "speed" | "delay"> = {},
) {
  const rate = rateOf(options.speed);
  if (rate === 0) return 1;
  const delay = Math.max(0, finite(options.delay, squiggleDefaults.delay));
  const { duration } = getSquiggleTimeline(options);
  return Math.max(1, Math.ceil(delay + duration / rate));
}

function getSquiggleTime(
  frame: number,
  options: Pick<SquiggleOptions, "fps" | "speed" | "delay"> = {},
) {
  const fps = Math.max(1, finite(options.fps, 30));
  const delay = Math.max(0, finite(options.delay, squiggleDefaults.delay));
  const elapsed = Math.max(0, finite(frame, 0) - delay);
  return (elapsed * 30 * rateOf(options.speed)) / fps;
}

function getSquiggleHead(
  time: number,
  timeline: SquiggleTimeline = getSquiggleTimeline(),
) {
  const t = time - timeline.drawAt;
  if (!(t > 0)) return 0;
  return easeOutQuart(Math.min(1, t / timeline.draw));
}

function getSquiggleTail(
  time: number,
  timeline: SquiggleTimeline = getSquiggleTimeline(),
) {
  if (!timeline.erase) return 0;
  const progress = (time - timeline.eraseStart) / timeline.eraseLength;
  if (!(progress > 0)) return 0;
  return easeInOutCubic(Math.min(1, progress));
}

function getSquiggleCalm(
  time: number,
  timeline: SquiggleTimeline = getSquiggleTimeline(),
) {
  const t = time - timeline.settleAt;
  if (!(t > 0)) return 0;
  return easeInOutSine(Math.min(1, t / timeline.settle));
}

function getSquigglePhase(
  time: number,
  timeline: SquiggleTimeline = getSquiggleTimeline(),
) {
  const t = time - timeline.settleAt;
  const swim = t > 0 ? easeOutCubic(Math.min(1, t / timeline.settle)) : 0;
  return SWIM * swim + EXIT_SWIM * getSquiggleTail(time, timeline);
}

function getSquiggleEnvelope(
  s: number,
  length: number,
  wavelength: number,
) {
  const taper = Math.min(wavelength, length / 3);
  if (!(taper > 0)) return 0;
  return smoothstep(s / taper) * smoothstep((length - s) / taper);
}

function getZigzagCurve(
  length: number,
  wavelength: number,
  amplitude: number,
  shift: number,
) {
  const k = (2 * Math.PI) / wavelength;
  const points: SquigglePoint[] = [{ x: 0, y: 0 }];
  const first = Math.floor(-(Math.PI / 2 + shift) / Math.PI) + 1;
  for (let m = first; points.length < MAX_POINTS - 1; m++) {
    const s = (Math.PI / 2 + m * Math.PI + shift) / k;
    if (s >= length) break;
    if (s <= 0) continue;
    const side = m % 2 === 0 ? 1 : -1;
    const w = getSquiggleEnvelope(s, length, wavelength);
    points.push({ x: s, y: side * amplitude * w });
  }
  points.push({ x: length, y: 0 });
  return points;
}

function getSquiggleCurve(input: SquiggleCurveInput) {
  const shape = shapeOf(input.shape);
  const length = Math.max(0, finite(input.length, 0));
  const wavelength = Math.max(1e-3, finite(input.wavelength, 1));
  const amplitude = Math.max(0, finite(input.amplitude, 0));
  const unit = Math.max(1e-3, finite(input.unit, 1));
  const shift = 2 * Math.PI * finite(input.phase, 0);
  if (shape === "zigzag") {
    return getZigzagCurve(length, wavelength, amplitude, shift);
  }
  const k = (2 * Math.PI) / wavelength;
  const gate = smoothstep(amplitude / (LOOP_FLOOR * unit));
  const reach = (REACH[shape] / k) * gate;
  const fine = wavelength / (SAMPLES[shape] * Math.max(1, unit));
  const coarsest = Math.max(length / MIN_POINTS, 1e-6);
  const step = clamp(fine, length / (MAX_POINTS - 2), coarsest);
  const sample = (s: number): SquigglePoint => {
    const w = getSquiggleEnvelope(s, length, wavelength);
    const theta = k * s - shift;
    if (shape === "wave") return { x: s, y: amplitude * w * Math.sin(theta) };
    const along = s - reach * w * Math.sin(theta);
    return { x: along, y: -amplitude * w * Math.cos(theta) };
  };
  const offset = (((shift / k) % step) + step) % step;
  const points = [sample(0)];
  for (let j = 0; points.length < MAX_POINTS - 1; j++) {
    const s = offset + j * step;
    if (s >= length) break;
    if (s > 0) points.push(sample(s));
  }
  points.push(sample(length));
  return points;
}

function getSquiggleTrim(
  points: readonly SquigglePoint[],
  tail: number,
  head: number,
) {
  const lengths = [0];
  for (let i = 1; i < points.length; i++) {
    const a = points[i - 1];
    const b = points[i];
    lengths.push(lengths[i - 1] + Math.hypot(b.x - a.x, b.y - a.y));
  }
  const last = points.length - 1;
  const total = last > 0 ? lengths[last] : 0;
  const from = clamp(finite(tail, 0), 0, 1) * total;
  const to = clamp(finite(head, 0), 0, 1) * total;
  const trimmed: SquigglePoint[] = [];
  if (last < 1 || !(to - from > EPSILON)) return { total, points: trimmed };
  const pointAt = (distance: number, index: number): SquigglePoint => {
    const a = points[index - 1];
    const b = points[index];
    const span = lengths[index] - lengths[index - 1];
    const t = span > 0 ? (distance - lengths[index - 1]) / span : 0;
    return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
  };
  let index = 1;
  while (index < last && lengths[index] < from) index++;
  trimmed.push(pointAt(from, index));
  while (index < last && lengths[index] < to) {
    trimmed.push(points[index]);
    index++;
  }
  trimmed.push(pointAt(to, index));
  return { total, points: trimmed };
}

function getSquigglePath(points: readonly SquigglePoint[]) {
  let path = "";
  let previous = "";
  for (const point of points) {
    const pair = `${round(point.x)} ${round(point.y)}`;
    if (pair === previous) continue;
    path += `${path === "" ? "M" : "L"}${pair}`;
    previous = pair;
  }
  return path;
}

/** `tl` is the resolved schedule; without it the one `options` give. */
function getSquiggleState(
  frame: number,
  options: SquiggleOptions = {},
  tl: ResolvedTimeline<SquiggleElementId> = scheduleOf(options),
) {
  const width = Math.max(1, finite(options.width, 1280));
  const height = Math.max(1, finite(options.height, 720));
  const unit = height / 720;
  const shape = shapeOf(options.shape);
  const timeline = getSquiggleTimeline(options, tl);
  const time = getSquiggleTime(frame, options);
  const head = getSquiggleHead(time, timeline);
  const tail = getSquiggleTail(time, timeline);
  const phase = getSquigglePhase(time, timeline);
  const settle = clamp(finite(options.settle, squiggleDefaults.settle), 0, 1);
  const lively = finite(options.amplitude, squiggleDefaults.amplitude);
  const calm = 1 - settle * getSquiggleCalm(time, timeline);
  const amplitude = Math.max(0, lively) * unit * calm;
  const length = Math.max(0, finite(options.length, squiggleDefaults.length));
  const course = length * unit;
  const cycle = finite(options.wavelength, squiggleDefaults.wavelength);
  const wavelength = Math.max(MIN_WAVELENGTH, cycle) * unit;
  const weight = Math.max(0, finite(options.weight, squiggleDefaults.weight));
  const angle = finite(options.angle, squiggleDefaults.angle);
  const radians = (angle * Math.PI) / 180;
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);
  const start = {
    x: finite(options.x, squiggleDefaults.x) * width,
    y: finite(options.y, squiggleDefaults.y) * height,
  };
  const end = { x: start.x + course * cos, y: start.y + course * sin };
  const drawn = head - tail > 0;
  const curve: SquigglePoint[] = drawn
    ? getSquiggleCurve({
        shape,
        length: course,
        wavelength,
        amplitude,
        phase,
        unit,
      })
    : [];
  const placed = curve.map((point) => ({
    x: start.x + point.x * cos - point.y * sin,
    y: start.y + point.x * sin + point.y * cos,
  }));
  const trim = getSquiggleTrim(placed, tail, head);
  const path = getSquigglePath(trim.points);
  return {
    width,
    height,
    unit,
    shape,
    time,
    timeline,
    head,
    tail,
    phase,
    amplitude,
    wavelength,
    length: course,
    strokeWidth: round(weight * unit),
    join: joinOf(shape),
    start,
    end,
    total: trim.total,
    points: trim.points,
    path,
    visible: path.includes("L"),
  };
}

type SquiggleState = ReturnType<typeof getSquiggleState>;

function SquiggleBase(props: SquiggleProps) {
  const {
    shape = squiggleDefaults.shape,
    x = squiggleDefaults.x,
    y = squiggleDefaults.y,
    length = squiggleDefaults.length,
    angle = squiggleDefaults.angle,
    amplitude = squiggleDefaults.amplitude,
    wavelength = squiggleDefaults.wavelength,
    weight = squiggleDefaults.weight,
    color = squiggleDefaults.color,
    settle = squiggleDefaults.settle,
    hold = squiggleDefaults.hold,
    erase = squiggleDefaults.erase,
    delay = squiggleDefaults.delay,
    speed = squiggleDefaults.speed,
    className,
    timing,
  } = props;
  const frame = useSceneFrame();
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    squiggleTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const state = getSquiggleState(
    frame,
    {
      shape,
      x,
      y,
      length,
      angle,
      amplitude,
      wavelength,
      weight,
      settle,
      hold,
      erase,
      delay,
      speed,
      width,
      height,
      fps,
    },
    tl,
  );

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label="SquiggleBase line"
        style={{ display: "block" }}
      >
        {state.visible ? (
          <path
            d={state.path}
            fill="none"
            stroke={color}
            strokeWidth={state.strokeWidth}
            strokeLinecap="round"
            strokeLinejoin={state.join}
          />
        ) : null}
      </svg>
    </div>
  );
}

