const ELEMENT_PROP_KEYS = new Set(["shape","color","weight","amplitude","wavelength","length","angle","x","y","settle","hold","erase","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  shape: "wave",
  color: "#ffffff",
  weight: 3,
  amplitude: 14,
  wavelength: 48,
  length: 320,
  angle: 0,
  x: 0.375,
  y: 0.5,
  settle: 0.5,
  hold: 12,
  erase: true,
  delay: 0,
  speed: 1,
};

type SquiggleElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof SquiggleBase>;

const SquiggleInner = forwardRef<
  HTMLDivElement,
  SquiggleElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<Squiggle>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <SquiggleBase
          {...(componentProps as unknown as ComponentProps<typeof SquiggleBase>)}
        />
      </div>
    </Sequence>
  );
});

export const Squiggle = Interactive.withSchema({
  Component: SquiggleInner,
  componentName: "<Squiggle>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
